// P2.3/P2.4: floating Kindly icon in an isolated Shadow DOM, anchored to
// the bottom-right of the active field and tracking it on scroll/resize/growth.

import { FLOATING_ICON_64_DATA_URI } from '../shared/assets';

const ICON_SIZE = 38;
const EDGE_INSET = 6;
const VIEWPORT_MARGIN = 8;

// Floating glyph embedded as a data URI (generated by scripts/make-icons.mjs).
const ICON_HTML = `<img src="${FLOATING_ICON_64_DATA_URI}" width="30" height="30" alt="" style="display:block;width:100%;height:100%;object-fit:contain" />`;

export class KindlyIcon {
  private host: HTMLDivElement;
  private button: HTMLButtonElement;
  private field: HTMLElement | null = null;
  private resizeObserver: ResizeObserver | null = null;
  private rafId = 0;

  constructor(
    private onClick: (field: HTMLElement) => void,
    private onHideSite: () => void,
  ) {
    this.host = document.createElement('div');
    this.host.style.cssText =
      'position:fixed;top:0;left:0;z-index:2147483647;pointer-events:none;display:none;visibility:hidden;';
    const shadow = this.host.attachShadow({ mode: 'open' });
    shadow.innerHTML = `
      <style>
        button {
          pointer-events: auto;
          width: ${ICON_SIZE}px;
          height: ${ICON_SIZE}px;
          border: none;
          border-radius: 50%;
          background: transparent;
          cursor: pointer;
          display: flex;
          align-items: center;
          justify-content: center;
          padding: 0;
        }
        button img {
          filter: drop-shadow(0 1px 3px rgba(0,0,0,0.4));
        }
        button:hover { opacity: 1; transform: scale(1.08); }
        button:focus-visible { outline: 2px solid #fff; outline-offset: 2px; }
        .quiet { opacity: 0.55; }
      </style>
      <button type="button" aria-label="Open Kindly" title="Kindly">${ICON_HTML}</button>
    `;
    this.button = shadow.querySelector('button') as HTMLButtonElement;
    // Keep focus in the field: without this, mousedown blurs the field and
    // sites like Gmail re-render it, removing the icon before click fires.
    this.button.addEventListener('mousedown', (e) => {
      e.preventDefault();
    });
    this.button.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      if (this.field) this.onClick(this.field);
    });
    this.button.addEventListener('contextmenu', (e) => {
      e.preventDefault();
      e.stopPropagation();
      this.onHideSite();
    });
    (document.documentElement || document.body).appendChild(this.host);

    window.addEventListener('scroll', this.scheduleUpdate, { capture: true, passive: true });
    window.addEventListener('resize', this.scheduleUpdate, { passive: true });
  }

  /** Show the icon anchored to the field's bottom-right corner. */
  show(field: HTMLElement, quiet = false) {
    this.field = field;
    this.button.classList.toggle('quiet', quiet);
    this.host.style.display = 'block';
    this.host.style.visibility = 'hidden'; // until a valid position is computed
    if (this.resizeObserver && this.field) this.resizeObserver.disconnect();
    this.resizeObserver = new ResizeObserver(() => this.scheduleUpdate());
    this.resizeObserver.observe(field);
    this.updatePosition();
    // updatePosition() may have hidden us again (detached/zero-rect field).
    if (this.host.style.display !== 'none') {
      this.host.style.visibility = 'visible';
    }
  }

  setQuiet(quiet: boolean) {
    this.button.classList.toggle('quiet', quiet);
  }

  hide() {
    this.host.style.display = 'none';
    this.host.style.visibility = 'hidden';
    this.field = null;
    this.resizeObserver?.disconnect();
    this.resizeObserver = null;
  }

  destroy() {
    window.removeEventListener('scroll', this.scheduleUpdate, { capture: true });
    window.removeEventListener('resize', this.scheduleUpdate);
    this.resizeObserver?.disconnect();
    if (this.rafId) cancelAnimationFrame(this.rafId);
    this.host.remove();
  }

  private scheduleUpdate = () => {
    if (this.rafId) return;
    this.rafId = requestAnimationFrame(() => {
      this.rafId = 0;
      this.updatePosition();
    });
  };

  private updatePosition() {
    if (!this.field || !this.field.isConnected) {
      this.hide();
      return;
    }
    const rect = this.field.getBoundingClientRect();
    if (rect.width === 0 && rect.height === 0) {
      this.hide();
      return;
    }

    // Bottom-right corner, inside the field when there's room.
    let left = rect.right - ICON_SIZE - EDGE_INSET;
    let top = rect.bottom - ICON_SIZE - EDGE_INSET;

    // If the field is shorter than the icon, center it vertically instead.
    if (rect.height < ICON_SIZE + EDGE_INSET * 2) {
      top = rect.top + rect.height / 2 - ICON_SIZE / 2;
    }

    // Keep inside the viewport.
    left = Math.min(Math.max(left, VIEWPORT_MARGIN), window.innerWidth - ICON_SIZE - VIEWPORT_MARGIN);
    top = Math.min(Math.max(top, VIEWPORT_MARGIN), window.innerHeight - ICON_SIZE - VIEWPORT_MARGIN);

    this.host.style.transform = `translate(${Math.round(left)}px, ${Math.round(top)}px)`;
    this.host.style.visibility = 'visible';
  }
}
